:root {
  --warm: #d9672b;
  --warm-ink: #8a3a0f;
  --warm-bg: #fdf1e8;
  --tone-1-a: #f6b26b; --tone-1-b: #d9672b;
  --tone-2-a: #a7d7b8; --tone-2-b: #2f7a5a;
  --tone-3-a: #a9cbf2; --tone-3-b: #2455b5;
