Used by .tone-1 to .tone-6 (stories.css:19-24): `background: linear-gradient(140deg, var(--tone-N-a), var(--tone-N-b))`. The class comes from TodayHome.tsx:13 `export function coverClass(number: number) { return `episode-cover tone-${((number - 1) % 6) + 1}`; }`. videos.css:16-17,21 reuse --tone-3 and --tone-5 for .video-poster and .kind-verhaal. The --warm tokens are used at stories.css:50,52,59,64,66,68,100 (streak ring, goal bar, day dots, words card, read-aloud recording).

.icon-tile { width: 45px; height: 45px; display: inline-flex; align-items: center; justify-content: center; border-radius: 13px; flex-shrink: 0; }
.icon-tile.small { width: 36px; height: 36px; border-radius: 10px; }
.sage { background: #e7efe7; color: #52755c; }
.sand { background: #efe8d4; color: #958052; }
.lilac { background: #ede8f5; color: #8776a1; }
.peach { background: #f5e7df; color: #b17b60; }
The colour names come from the `skills` export in LearningOverview.tsx:7-44 (color: "sage" | "sand" | "lilac" | "peach" at lines 19, 26, 33, 40). They are rendered at ProgressOverview.tsx:60 `<span className={`icon-tile ${color}`}>`, ProgressOverview.tsx:109 `icon-tile small sage`, and AccountSettings.tsx:51 `icon-tile small sage` / :95 `icon-tile small sand`.

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
  }
}
Plus stories.css:45 `@media (prefers-reduced-motion: reduce) { .writing-dots span { animation: none; opacity: .7; } }` and library.css:35 `@media(prefers-reduced-motion:reduce) { .story-tile,.vocabulary-card { transition:none; } }`.

export class ApiError extends Error { constructor(public readonly status: number, public readonly detail: string, public readonly requestId: string) { super(`${status}: ${detail}`); } }
export function newRequestId(): string  // crypto.randomUUID() without dashes (32 hex), else `r${Date.now().toString(36)}${random}`
export interface ApiOptions { method?: "GET" | "POST" | "PUT" | "PATCH" | "DELETE"; body?: unknown; formData?: FormData; requestId?: string; signal?: AbortSignal }
export const CONNECTIVITY_EVENT = "dlp:connectivity";
export async function apiFetch(path: string, options: ApiOptions = {}): Promise<Response>
export async function apiJson<T>(path: string, options: ApiOptions = {}): Promise<T>

